// Ghép dữ liệu 5 sheet + yêu cầu từ webhook thành payload cho Brain /tools.
// Toàn bộ TÍNH TOÁN nằm ở Brain (P1) — node này chỉ chở và lọc dữ liệu.
const req = $('Nhận yêu cầu báo giá').first().json.body || {};
const need = ['origin', 'destination', 'vehicle_type'];
for (const k of need) {
  if (!req[k]) throw new Error('Thiếu trường bắt buộc: ' + k);
}

const carriers = $('Đọc Carriers').all().map(i => i.json);
const quotes   = $('Đọc CarrierQuotes').all().map(i => i.json);
const rules    = $('Đọc PricingRules').all().map(i => i.json);
const fuels    = $('Đọc FuelIndex').all().map(i => i.json);
const routes   = $('Đọc Routes').all().map(i => i.json);

// NGÀY chỉ nhận ISO (YYYY-MM-DD, có thể kèm giờ). Bản trước so CHUỖI THÔ, nên một ô
// kiểu DD/MM/YYYY (locale Việt Nam của Google Sheets) bị so sai chiều: "15/07/2999" <
// "2026-11-12" -> giá còn hiệu lực bị loại; "31/12/2000" > "2026-11-12" -> giá ĐÃ HẾT
// HẠN lại được dùng. Cố ý KHÔNG đoán DD/MM hay MM/DD (05/11 là 5 tháng 11 hay 11 tháng
// 5 tuỳ locale): không đọc được thì trả null và đếm vào `canh_bao_du_lieu`.
const ngayIso = v => {
  const k = /^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/.exec(String(v == null ? '' : v).trim());
  if (!k) return null;
  const y = +k[1], m = +k[2], d = +k[3];
  const t = new Date(Date.UTC(y, m - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) return null;
  return t.toISOString().slice(0, 10);
};
const canhBao = [];
// Ô ngày TRỐNG = không giới hạn (cố ý). Ô CÓ chữ mà không đọc được = KHÔNG dùng giá đó:
// không biết hạn thì không được coi là còn hạn.
const hieuLuc = (q, cot, ok) => {
  const v = q[cot];
  if (v == null || String(v).trim() === '') return true;
  const dd = ngayIso(v);
  if (dd === null) {
    canhBao.push('Bỏ giá chào ' + q.carrier_id + ' (tuyến ' + q.route_id + '): ' + cot +
      ' = "' + v + '" không phải YYYY-MM-DD');
    return false;
  }
  return ok(dd);
};

// Giá dầu MỚI NHẤT (AGENTS.md 3.1c — realtime: lấy tại thời điểm gọi)
// Chỉ xét dòng có ngày ĐỌC ĐƯỢC (so theo ngày đã chuẩn hoá, không so chuỗi thô).
const fuel = fuels.filter(f => f.fuel_type === 'diesel' && ngayIso(f.date) !== null)
  .sort((a, b) => ngayIso(b.date).localeCompare(ngayIso(a.date)))[0] || null;
const fuelBoQua = fuels.filter(f => f.fuel_type === 'diesel' && ngayIso(f.date) === null).length;
if (fuelBoQua) canhBao.push('Bỏ ' + fuelBoQua + ' dòng FuelIndex có ngày không phải YYYY-MM-DD');
// Ngày của giá dầu, để Brain GHI LẠI báo giá dựa trên giá dầu ngày nào. Chỉ đưa
// khi đúng YYYY-MM-DD: Brain từ chối định dạng khác (422) thay vì đoán ngày.
const fuelAsOf = fuel ? ngayIso(fuel.date) : null;

// So khớp tên địa điểm không phân biệt hoa/thường, dấu, khoảng trắng thừa.
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/đ/g, 'd').replace(/\s+/g, ' ').trim();

// TUYẾN. Bản trước KHÔNG đọc sheet Routes và lọc giá chào chỉ theo loại xe, nên
// nhà xe có giá chào cho nhiều tuyến bị lẫn lộn: Brain giữ giá chào CUỐI của mỗi
// nhà xe, tức có thể báo giá tuyến Bắc Ninh bằng giá tuyến Bắc Giang — sai, im
// lặng, và gửi tới khách. Thiếu tuyến thì DỪNG và nói rõ, không đoán.
const khop = routes.filter(r =>
  norm(r.origin) === norm(req.origin) && norm(r.destination) === norm(req.destination));
if (khop.length === 0) {
  throw new Error('Chưa có tuyến ' + req.origin + ' → ' + req.destination +
    ' trong sheet Routes — thêm tuyến (và giá chào của tuyến đó) rồi báo giá lại');
}
if (khop.length > 1) {
  throw new Error('Sheet Routes có ' + khop.length + ' dòng cùng tuyến ' + req.origin +
    ' → ' + req.destination + ' (id: ' + khop.map(r => r.id).join(', ') +
    ') — mỗi tuyến chỉ được một dòng');
}
const route = khop[0];

// Lọc giá chào còn hiệu lực cho ĐÚNG TUYẾN + loại xe (cả valid_from lẫn valid_to)
const today = new Date().toISOString().slice(0, 10);
const validQuotes = quotes.filter(q =>
  String(q.route_id) === String(route.id) &&
  q.vehicle_type === req.vehicle_type &&
  hieuLuc(q, 'valid_from', dd => dd <= today) &&
  hieuLuc(q, 'valid_to', dd => dd >= today)
);

// Quy tắc giá: khớp cargo_type nếu có, không thì 'Mặc định'
const rule = rules.find(r => r.name === (req.cargo_type || '')) ||
             rules.find(r => r.name === 'Mặc định') || rules[0];
if (!rule) throw new Error('Chưa có PricingRules — khách cần nhập quy tắc giá trước');

const payloadSelection = {
  carriers: carriers.map(c => ({
    id: String(c.id), name: c.name,
    vehicle_types: String(c.vehicle_types || '').split('|').filter(Boolean),
    depot_lat: c.depot_lat ? Number(c.depot_lat) : null,
    depot_lon: c.depot_lon ? Number(c.depot_lon) : null,
    discount_pct: c.discount_pct ? Number(c.discount_pct) : null,
    credit_days: c.credit_days ? Number(c.credit_days) : null,
    years_partner: c.years_partner ? Number(c.years_partner) : null
  })),
  offers: validQuotes.map(q => ({ carrier_id: String(q.carrier_id), price: Number(q.price) })),
  request: {
    origin: req.origin, destination: req.destination,
    // Toạ độ điểm đi lấy từ Routes. Bản trước không truyền nên tiêu chí "gần
    // bãi xe" luôn là null và bị bỏ khỏi bảng điểm.
    origin_lat: route.origin_lat ? Number(route.origin_lat) : null,
    origin_lon: route.origin_lon ? Number(route.origin_lon) : null,
    vehicle_type: req.vehicle_type, cargo_type: req.cargo_type || null,
    pickup_date: req.pickup_date || null
  }
};

return [{ json: {
  req, rule,
  route_id: String(route.id),
  current_fuel_price: fuel ? Number(fuel.price) : null,
  fuel_date: fuel ? fuel.date : null,
  fuel_price_as_of: fuelAsOf,
  canh_bao_du_lieu: canhBao,
  payloadSelection
}}];

// Lấy hãng đứng đầu + dựng payload tính báo giá.
const ctx = $('Ghép dữ liệu').first().json;
const sel = $input.first().json;
if (!sel.ranked || !sel.ranked.length) {
  throw new Error('Không có hãng xe phù hợp: ' + JSON.stringify(sel.rejected || []));
}
const top = sel.ranked[0];
const rule = ctx.rule;
return [{ json: {
  selection: sel,
  top,
  quotePayload: {
    carrier_cost: Number(top.offer_price),
    pricing_rule: {
      base_margin_pct: Number(rule.base_margin_pct),
      fuel_sensitivity: Number(rule.fuel_sensitivity || 0.35),
      fuel_baseline_price: rule.fuel_baseline_price ? Number(rule.fuel_baseline_price) : null,
      min_margin_amount: Number(rule.min_margin_amount || 0),
      surcharges: rule.surcharge_name ? [{
        name: rule.surcharge_name,
        amount: Number(rule.surcharge_amount || 0),
        pct: Number(rule.surcharge_pct || 0)
      }] : []
    },
    current_fuel_price: ctx.current_fuel_price,
    fuel_price_as_of: ctx.fuel_price_as_of
  }
}}];

// Dựng bản nháp + embed Discord cho CHỦ DN duyệt.
// P2: breakdown nội bộ (internal, có biên) CHỈ đi Discord chủ DN —
// KHÔNG BAO GIỜ vào email khách cuối (email dựng ở workflow approve, chỉ từ 'quote').
const ctx  = $('Ghép dữ liệu').first().json;
const pick = $('Lấy hãng đầu bảng').first().json;
const q    = $input.first().json;
const req  = ctx.req;

const id = 'QD-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' +
           Math.random().toString(36).slice(2, 6).toUpperCase();
const vn = n => new Intl.NumberFormat('vi-VN').format(n);

const draftRow = {
  id,
  created_at: new Date().toISOString(),
  status: 'pending',
  customer_name: req.customer_name || '',
  customer_email: req.customer_email || '',
  origin: req.origin, destination: req.destination,
  vehicle_type: req.vehicle_type, cargo_type: req.cargo_type || '',
  pickup_date: req.pickup_date || '',
  carrier_id: String(pick.top.carrier_id), carrier_name: pick.top.name,
  quoted_price: q.quote.quoted_price,
  surcharges_json: JSON.stringify(q.quote.surcharges),
  internal_json: JSON.stringify({ internal: q.internal, warnings: q.warnings, fuel_date: ctx.fuel_date, route_id: ctx.route_id }),
  approved_at: ''
};

const approveUrl = ($env.N8N_PUBLIC_URL || '') + '/webhook/logistics-approve?draft_id=' + id;
const warn = (q.warnings || []).map(w => '⚠️ ' + w).join('\n');
const closeCall = pick.selection.explain && pick.selection.explain.is_close_call
  ? '\n⚠️ Hai hãng đầu bảng điểm sát nhau — cân nhắc tự chọn.' : '';

const body = { embeds: [{
  title: '📋 Nháp báo giá ' + id + ' — CHỜ DUYỆT',
  color: 16744448,
  description:
    '**Tuyến:** ' + req.origin + ' → ' + req.destination + ' | ' + req.vehicle_type +
    (req.cargo_type ? ' | ' + req.cargo_type : '') + '\n' +
    '**Khách:** ' + (req.customer_name || '?') + ' <' + (req.customer_email || '?') + '>\n\n' +
    '**GIÁ BÁO KHÁCH: ' + vn(q.quote.quoted_price) + ' đ**\n\n' +
    '_Nội bộ (không gửi khách):_\n' +
    '• Hãng: ' + pick.top.name + ' — giá gốc ' + vn(q.internal.carrier_cost) + ' đ\n' +
    '• Điều chỉnh dầu: ' + vn(q.internal.fuel_adjustment) + ' đ (giá dầu ngày ' + (ctx.fuel_date || '?') + ')\n' +
    '• Biên: ' + vn(q.internal.margin) + ' đ (' + q.internal.margin_pct_effective + '%)\n' +
    (warn ? warn + '\n' : '') + closeCall + '\n\n' +
    '✅ Duyệt & gửi email: ' + approveUrl,
  footer: { text: 'ANSER Logistics • nháp → duyệt → gửi' },
  timestamp: new Date().toISOString()
}]};

return [{ json: { draftRow, discord_body: JSON.stringify(body), draft_id: id } }];
